export interface Options {
  description?: string;
  title?: string;
}
export interface Text {
  "~kind": "Text";
  type: "string";
}
export interface Count {
  "~kind": "Count";
  type: "integer";
}
export interface List<Items> {
  "~kind": "List";
  type: "array";
  items: Items;
}
export interface Shape<Properties> {
  "~kind": "Shape";
  type: "object";
  required: string[];
  properties: Properties;
}
export type Optional<Schema> = Schema & { "~optional": true };
export declare function text(options?: Options): Text;
export declare function count(options?: Options): Count;
export declare function optional<Schema>(schema: Schema): Optional<Schema>;
export declare function list<Items>(items: Items, options?: Options): List<Items>;
export declare function shape<Properties>(properties: Properties, options?: Options): Shape<Properties>;
export declare function kindOf(schema: unknown): string | undefined;
export declare function isKind(schema: unknown, kind: string): boolean;
export declare function describe(schema: unknown): string;
export declare function check(schema: unknown, value: unknown): boolean;
